{
  "$defs": {
    "AppSpec": {
      "additionalProperties": false,
      "properties": {
        "builder": {
          "default": "auto",
          "description": "`\"auto\"` (detect the stack, use the Paketo builder), `\"heroku\"`, or an\nexplicit builder image reference — the last one REQUIRES `runImage`\n(this engine does not introspect a custom builder's own `builder.toml`\nto discover its run image; refusing is the honest answer, not a guess).",
          "type": "string"
        },
        "image": {
          "description": "Tag the built image gets in the LOCAL `ImageStore` once the build\nsucceeds.",
          "type": "string"
        },
        "runImage": {
          "default": null,
          "type": [
            "string",
            "null"
          ]
        },
        "source": {
          "default": ".",
          "description": "Directory to build (Compose-style relative-to-CWD default, same\nconvention `kind: Image`'s `build.context` already uses — not the\nmanifest file's own directory).",
          "type": "string"
        }
      },
      "required": [
        "image"
      ],
      "type": "object"
    },
    "ApplicationSpec": {
      "additionalProperties": false,
      "description": "`spec` of `kind: Application`: a [`super::container::PodSpec`] (`containers[]`,\n`network`, …) plus `replicas`. Each instance is one `kind: Pod` whose spec is\nthis one with `replicas` removed.",
      "properties": {
        "containers": {
          "items": {
            "$ref": "#/$defs/PodContainer"
          },
          "type": "array"
        },
        "detach": {
          "default": true,
          "type": "boolean"
        },
        "expose": {
          "default": null,
          "description": "delonix extension: auto-register an HTTP port in the L7 proxy.",
          "format": "uint16",
          "maximum": 65535,
          "minimum": 0,
